import math

def combinations(n, k):
    if k < 0 or k > n:
        return 0
    if k == 0 or k == n:
        return 1
    if k > n // 2:
        k = n - k

    num = 1
    for i in range(k):
        num = num * (n - i) // (i + 1)
    return num

def check_n(n):
    if math.gcd(n, 6) != 1:
        return False

    a_start = n // 3 + 1
    a_end = n // 2

    for a in range(a_start, a_end + 1):
        if n // a != 2:
            return False

        div = n - 2 * a
        if div == 0:
            continue

        val = combinations(a - 1, n - 2 * a - 1)
        if val % div != 0:
            return False

    return True

count = 0
working_ns = []
for n in range(2, 200):
    if check_n(n):
        count += 1
        working_ns.append(n)

